import json,subprocess,re
from pathlib import Path
root=Path('/home/admin1/projects/ai-core')
sources=[root/'.env',root/'.env.local',root/'router/.env',root/'runtime/.env',Path('/home/admin1/projects/debug-ai/.env'),Path('/home/admin1/projects/debug-ai/.env.local'),Path('/home/admin1/.config/ai-core/.env')]
