   for line in fp.read_text(errors='replace').splitlines()[:500]:
    m=re.match(r'^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=',line)
    if m:names.add(m.group(1))
   entry['matching_secret_names']=[s for s in want if s in names]
   if fp==root/'.env':entry['other_env_variable_names']=sorted(names)[:40]
  except OSError:entry['readable']=False
 files.append(entry)
services=['debug-ai','ai-llama-router','ai-core-model-gate','ai-qwen3','ai-coder']
containers=[]
for name in services:
 p=subprocess.run(['docker','inspect','--format','{{json .Config.Env}}',name],capture_output=True,text=True,timeout=8)
 row={'name':name,'present':p.returncode==0}
 if p.returncode==0:
  try:
   names={v.split('=',1)[0] for v in json.loads(p.stdout)}
   row['matching_secret_names']=[s for s in want if s in names]
  except (ValueError,TypeError):row['env_parse_failed']=True
 containers.append(row)
out={'file_sources':files,'container_env_name_presence':containers,'secret_values_collected':False}
body='AI_CORE_EXISTING_BEARER_SOURCE_DISCOVERY\n'+json.dumps(out,ensure_ascii=False,indent=2)
p=subprocess.run(['gh','api','-X','POST','repos/G-ACE-inc/server-core/issues/10/comments','--input','-','--jq','.html_url'],input=json.dumps({'body':body}),capture_output=True,text=True,timeout=20)
print('AI_CORE_BEARER_DISCOVERY='+('PASS '+p.stdout.strip() if p.returncode==0 else 'FAILED'))
raise SystemExit(0 if p.returncode==0 else 1)
